CREATE   PROCEDURE [synapse_ce].[usp_Insert_list]
AS
BEGIN

	INSERT INTO [synapse_ce].[list]
	(
		[Id],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[createdfromcode],
		[donotsendonoptout],
		[ignoreinactivelistmembers],
		[lockstatus],
		[msdyncrm_issubscription],
		[type],
		[createdby],
		[createdby_entitytype],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedonbehalfby],
		[modifiedonbehalfby_entitytype],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[ownerid],
		[ownerid_entitytype],
		[cost],
		[cost_base],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
		[description],
		[entityimage],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[importsequencenumber],
		[lastusedon],
		[listid],
		[listname],
		[membercount],
		[membertype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		[modifiedonbehalfbyname],
		[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunitname],
		[processedmembercount],
		[processfetchxml],
		[processid],
		[purpose],
		[query],
		[source],
		[stageid],
		[timezoneruleversionnumber],
		[transactioncurrencyidname],
		[traversedpath]
	)
	SELECT
		stg.[Id],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[createdfromcode],
		stg.[donotsendonoptout],
		stg.[ignoreinactivelistmembers],
		stg.[lockstatus],
		stg.[msdyncrm_issubscription],
		stg.[type],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdonbehalfby],
		stg.[createdonbehalfby_entitytype],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[cost],
		stg.[cost_base],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[description],
		stg.[entityimage],
		stg.[entityimage_timestamp],
		stg.[entityimage_url],
		stg.[entityimageid],
		stg.[exchangerate],
		stg.[importsequencenumber],
		stg.[lastusedon],
		stg.[listid],
		stg.[listname],
		stg.[membercount],
		stg.[membertype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunitname],
		stg.[processedmembercount],
		stg.[processfetchxml],
		stg.[processid],
		stg.[purpose],
		stg.[query],
		stg.[source],
		stg.[stageid],
		stg.[timezoneruleversionnumber],
		stg.[transactioncurrencyidname],
		stg.[traversedpath]
	FROM [staging_ce].[list] stg
		LEFT JOIN [synapse_ce].[list] tgt
			ON stg.[Id] = tgt.[Id]
	WHERE tgt.[Id] IS NULL

END
